import os
import re
from collections import defaultdict

ROOT = "/bench/repo"
STORE_PREFIX = os.path.join(ROOT, "store")

ENTITIES = [
    "Attachment", "IdentityProvider", "Inbox", "InstanceSetting",
    "Memo", "MemoRelation", "MemoShare", "Reaction",
    "User", "UserIdentity", "UserSetting",
]

# Pattern: store.EntityName (word boundary after entity name)
def entity_pattern(name):
    return re.compile(r'\bstore\.' + re.escape(name) + r'\b')

entity_patterns = {e: entity_pattern(e) for e in ENTITIES}

# Map package path -> set of entities referenced
pkg_entities = defaultdict(set)

for dirpath, dirnames, filenames in os.walk(ROOT):
    # Skip store layer entirely
    if dirpath == STORE_PREFIX or dirpath.startswith(STORE_PREFIX + os.sep):
        continue
    # Skip .git
    if '/.git' in dirpath:
        continue

    go_files = [f for f in filenames if f.endswith('.go')]
    if not go_files:
        continue

    # Determine Go package path (relative to repo root)
    rel_dir = os.path.relpath(dirpath, ROOT)
    if rel_dir == '.':
        pkg_path = ROOT  # unusual
    else:
        pkg_path = rel_dir

    for fname in go_files:
        fpath = os.path.join(dirpath, fname)
        try:
            with open(fpath, 'r', errors='replace') as f:
                content = f.read()
        except:
            continue

        for entity, pat in entity_patterns.items():
            if pat.search(content):
                pkg_entities[pkg_path].add(entity)

# Also count per entity
entity_pkg_count = defaultdict(set)
for pkg, entities in pkg_entities.items():
    for e in entities:
        entity_pkg_count[e].add(pkg)

print("=== Entity reference counts (distinct packages outside store/) ===\n")
ranked = sorted(ENTITIES, key=lambda e: (-len(entity_pkg_count[e]), e))
for e in ranked:
    pkgs = sorted(entity_pkg_count[e])
    print(f"{e}: {len(pkgs)} packages")
    for p in pkgs:
        print(f"  - {p}")
    print()

print("\n=== Top packages by number of entity types referenced ===")
for pkg in sorted(pkg_entities.keys(), key=lambda p: -len(pkg_entities[p]))[:5]:
    print(f"{pkg}: {sorted(pkg_entities[pkg])}")
PYEOF

