use strict;
use warnings;
use File::Find;

my @ENTITIES = qw(Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare Reaction User UserIdentity UserSetting);
my %entity_pkgs;
my %pkg_entities;
my $ROOT = "/bench/repo";

find(sub {
    return unless /\.go$/;
    my $path = $File::Find::name;
    return if $path =~ m{^/bench/repo/store(/|$)};
    return if $path =~ m{/.git/};

    open my $fh, "<", $path or return;
    my $content = do { local $/; <$fh> };
    close $fh;

    my $dir = $File::Find::dir;
    $dir =~ s{^/bench/repo/?}{};
    $dir = "." if $dir eq "";

    for my $e (@ENTITIES) {
        if ($content =~ /\bstore\.$e\b/) {
            $entity_pkgs{$e}{$dir} = 1;
            $pkg_entities{$dir}{$e} = 1;
        }
    }
}, $ROOT);

print "=== Entity reference counts (distinct packages outside store/) ===\n\n";
for my $e (sort { (keys %{$entity_pkgs{$b}} <=> keys %{$entity_pkgs{$a}}) || $a cmp $b } @ENTITIES) {
    my @pkgs = sort keys %{$entity_pkgs{$e} || {}};
    print "$e: ", scalar(@pkgs), " packages\n";
    for my $p (@pkgs) {
        print "  - $p\n";
    }
    print "\n";
}
'

